    schemaVersion: '1.0',
    id: 'topic-2026-000046',
    slug: 'music-publishers-canada-ai-copyright-intervention',
    title: {
      en: 'Music Publishers Canada Files to Intervene in Landmark AI and Copyright Federal Court Case',
      zh: '加拿大音樂出版商協會聲請介入指標性 AI 著作權聯邦法院案件',
    },
    summary: {
      en: "Billboard reports Music Publishers Canada (MPC) filed to intervene in a Canadian federal court case challenging a copyright registration the Canadian Intellectual Property Office granted to Ankit Sahni for an AI-modified image (Sahni used a generative tool to render his photograph in Vincent van Gogh's style, with the AI tool listed as a co-author). MPC's intervention, approved by the court in June 2026, argues that only a human can be a copyright author regardless of AI assistance, that courts should assess AI-assisted works contextually based on how creators used the tools, and that Canada's approach should align with international norms. MPC CEO Margaret McGuffin frames the stakes as extending beyond visual art to music and other creative industries, given the precedent the ruling would set.",
      zh: 'Billboard 報導,加拿大音樂出版商協會(MPC)聲請介入一起聯邦法院案件,該案挑戰加拿大智慧財產局核發給 Ankit Sahni 的一項著作權登記——Sahni 使用生成式工具將自己的照片轉換成梵谷風格,而該 AI 工具被列為共同作者。MPC 的介入聲請已於 2026 年 6 月獲法院核准,主張無論 AI 是否參與協助,著作權作者僅能是人類;法院應依創作者實際如何運用工具,逐案審酌其創作脈絡;加拿大的做法應與國際規範接軌。MPC 執行長 Margaret McGuffin 強調此案的影響不僅限於視覺藝術,鑑於判決可能樹立的先例,音樂與其他創意產業同樣攸關。',
    },
