    id: 'topic-2026-000047',
    slug: 'ropedia-funding-embodied-ai-data-collection',
    title: {
      en: 'Ropedia Raises $22M to Scale Human-Centric Data Collection for Embodied AI',
      zh: 'Ropedia 募得 2200 萬美元,擴大具身 AI 的人本資料蒐集規模',
    },
    summary: {
      en: "SiliconANGLE reports Singapore-based robotics-data startup Ropedia raised $22 million in Pre-Series A funding to scale HOMIE, a lightweight head-mounted wearable with four cameras that captures human physical activity as structured, synchronized video data for training embodied-AI/robotics foundation models. The piece frames the funding around a specific bottleneck: raw internet video lacks the geometric and trajectory metadata robots need for motor control, and existing datasets are too small and low-diversity to unlock general-purpose physical AI. CEO Zhaoxi Chen frames the goal as finding robotics' 'ChatGPT moment' before mass robot deployment becomes viable. The funding will scale HOMIE production toward 10,000 devices and expand hardware/software hiring and U.S. operations.",
      zh: 'SiliconANGLE 報導,新加坡機器人資料新創公司 Ropedia 完成 2200 萬美元 Pre-Series A 募資,用以擴大 HOMIE 的規模——這是一款配備四個鏡頭的輕量頭戴式穿戴裝置,能將人類的身體活動擷取為結構化、時間同步的影像資料,用來訓練具身 AI/機器人基礎模型。報導點出一個具體瓶頸:網路上現有的原始影片缺乏機器人動作控制所需的幾何與軌跡中繼資料,現有資料集規模太小、多樣性也不足,無法解鎖通用型的物理 AI。執行長 Zhaoxi Chen 將目標定位為:在機器人大規模部署真正可行之前,先找到機器人領域的「ChatGPT 時刻」。這筆資金將用於把 HOMIE 產能擴大至一萬台裝置,並擴充硬體/軟體團隊與美國營運。',
    },
    tag: { en: 'Embodied AI', zh: '具身 AI' },
    topics: ['embodied-ai'],
    contentType: 'news',
