    slug: 'nature-consciousness-research-ai-moment',
    title: {
      en: 'Consciousness Research Is Having an AI Moment. Will the Hype Help the Field?',
      zh: '意識研究正迎來屬於 AI 的時刻——這股熱潮對這門學科是好是壞?',
    },
    summary: {
      en: "A Nature news feature by Mariana Lenharo examines how surging public interest in AI sentience is reshaping consciousness science itself, not just AI research. It reports that Anthropic recently posted a non-peer-reviewed study suggesting it found something in Claude comparable to conscious thought, intensifying a debate researchers still can't resolve because there is no agreed account of what gives rise to consciousness even in humans. Anil Seth, a consciousness scientist at the University of Sussex, warns of a possible \"capture of consciousness research by the AI sector,\" in which computational searches for AI \"signatures\" of consciousness crowd out neuroscience and philosophy of how consciousness arises in biological brains — while other researchers welcome the attention and funding the AI hype is bringing to a field long treated as scientifically marginal.",
      zh: 'Nature 一篇由 Mariana Lenharo 撰寫的新聞特稿,探討大眾對 AI 是否具有感知能力的高度關注,如何重塑意識科學這門學科本身,而不只是影響 AI 研究。報導指出,Anthropic 近期發布一份未經同行審查的研究,主張在 Claude 身上找到某種可與人類意識思維相比擬的現象,進一步加劇一場研究者至今無法解決的爭論——因為就連人類意識從何而來,學界都尚無共識,遑論 AI。薩塞克斯大學意識科學家 Anil Seth 警告,這可能導致「意識研究被 AI 產業俘獲」,亦即以電腦運算方式尋找 AI 的意識「訊號」,反而排擠了探討生物大腦如何產生意識的神經科學與哲學研究;但也有研究者歡迎這股 AI 熱潮為長期被視為邊緣學科的意識研究,帶來更多關注與資金。',
    },
