    slug: 'china-ai-agent-anthropomorphic-ai-rules',
    title: {
      en: "China Introduces Operational Rules for AI Agents and Anthropomorphic AI",
      zh: '中國推出針對 AI 智能體與擬人化 AI 的可操作性規則',
    },
    summary: {
      en: "IAPP reports that China introduced three new regulatory developments in July 2026 addressing AI ethics, autonomous AI agents, and anthropomorphic AI (human-like emotional chatbots and digital avatars) — a shift from the broad principles of earlier rules like the Interim Measures for Generative AI Services toward more detailed, operational, risk-based requirements. The move responds to concrete harms that emerged as open-source AI agent technology spread rapidly since late 2025 (including credential theft, enterprise data leakage, and prompt-injection attacks that manipulated agents into unauthorized actions) and as AI companions and emotional chatbots grew more human-like, raising concerns about emotional dependence and psychological harm, particularly among minors and older adults.",
      zh: 'IAPP 報導,中國於 2026 年 7 月推出三項新的監理措施,針對 AI 倫理、自主 AI 智能體,以及擬人化 AI(具人類情感互動特徵的聊天機器人與數位分身)——相較於先前《生成式人工智慧服務管理暫行辦法》等偏向原則性的規範,這次轉向更細緻、可操作、以風險為基礎的具體要求。此舉是為了回應自 2025 年底以來,開源 AI 智能體技術快速擴散所浮現的具體危害(包括憑證竊取、企業資料外洩,以及誘騙智能體執行未授權動作的提示注入攻擊),以及 AI 陪伴應用與情感聊天機器人日益擬人化,所引發的情感依賴與心理傷害疑慮,尤其是對未成年人與長者而言。',
    },
