    id: 'topic-2026-000054',
    slug: 'usc-human-ai-cognition-brain-signals-study',
    title: {
      en: 'USC Researcher Studies How Humans and AI Think Together by Reading Brain Signals',
      zh: '南加大研究者透過腦訊號研究人類與 AI 如何「共同思考」',
    },
    summary: {
      en: "USC Viterbi School of Engineering reports on a new five-year, roughly $600,000 NSF CAREER Award-funded study led by assistant professor Souti (Rini) Chattopadhyay, examining how interacting with AI-powered agentic systems changes human creativity and critical thinking. The project measures brain signals alongside screen tracking and verbalized thought processes across healthcare, journalism, and software-engineering workflows to identify which kinds of human-AI interaction sharpen critical thinking versus introduce cognitive blind spots, with the stated goal of designing interaction guidelines for stronger human-AI synergy rather than treating AI as a replacement for human creative capacity.",
      zh: '南加州大學維特比工程學院報導一項新的五年期研究,由助理教授 Souti (Rini) Chattopadhyay 主持,獲美國國家科學基金會(NSF)約 60 萬美元的 CAREER Award 資助,探討與具能動性(agentic)的 AI 系統互動,如何改變人類的創造力與批判性思考。這項計畫將透過測量腦訊號、螢幕操作追蹤,以及口語化思考歷程,涵蓋醫療、新聞、軟體工程等工作情境,找出哪些類型的人機互動能強化批判性思考、哪些反而會造成認知盲點,目標是設計出能強化人機協同的互動準則,而非把 AI 當作取代人類創造力的工具。',
    },
