    id: 'topic-2026-000056',
    slug: 'publishers-authors-sue-google-gemini-copyright',
    title: {
      en: 'Publishers and Authors File Class Action Lawsuit Against Google Over Gemini Training Data',
      zh: '出版商與作者對 Google 提起集體訴訟,指控 Gemini 訓練資料侵權',
    },
    summary: {
      en: "The International Publishers Association reports that on July 10, 2026, Hachette Book Group, Cengage Learning, Elsevier, and bestselling author Scott Turow filed a putative class action lawsuit against Google in the US, alleging willful copyright infringement of millions of books and journal articles used to train Google's Gemini large language models. The complaint alleges Google copied works it had obtained under strictly limited terms — for services like Google Books and Google Play Books — and used them for AI training without consent or compensation. Publishers say they filed this separate suit, rather than relying solely on their status as intervenors in the ongoing In re Google Generative AI Copyright Litigation, specifically to preserve claims that fall outside that case's putative class.",
      zh: '國際出版商協會(IPA)報導,2026 年 7 月 10 日,Hachette Book Group、Cengage Learning、Elsevier 三家出版商與暢銷書作家 Scott Turow,於美國對 Google 提起集體訴訟,指控 Google 為訓練其 Gemini 大型語言模型,惡意侵犯數百萬本書籍與期刊文章的著作權。訴狀主張 Google 將原本僅限於 Google 圖書、Google Play 圖書等服務範圍內使用的作品予以複製,未經同意、未付費即用於 AI 訓練。出版商表示,之所以另外提起這宗獨立訴訟,而非僅依賴其在現有集體訴訟案 In re Google Generative AI Copyright Litigation 中的介入人身分,是為了保留該案訴訟類別範圍之外的其他求償權利。',
    },
