    schemaVersion: "1.0",
    id: "topic-2026-000062",
    slug: "gcc-bans-ai-generated-code-gpl-copyright",
    title: {
      en: "GCC Bans Substantial AI-Generated Code Contributions Over GPL Copyright Concerns",
      zh: "GCC 因 GPL 著作權疑慮,禁止大量 AI 生成程式碼貢獻",
    },
    summary: {
      en: "Northeast Times reports that the GNU Compiler Collection (GCC) Steering Committee announced on July 29, 2026 that it will reject any \"legally significant\" code contribution generated by or derived from large language models, following a recommendation from a GCC AI Policy Working Group. The threshold for \"legally significant\" — roughly 15 lines of code or text — comes from existing GNU Project maintainer guidelines; below that line, contributors may still submit small AI-assisted fixes if tagged with an \"Assisted-by:\" commit header, and test cases are fully exempt. The policy does not restrict using AI tools for research, bug discovery, or code review — only output that ends up directly in a contribution — and reflects concern that GPL copyleft licensing depends on contributors holding clear copyright over their own work, which is legally uncertain for LLM-generated code.",
      zh: "Northeast Times 報導,GNU 編譯器套件(GCC)指導委員會於 2026 年 7 月 29 日宣布,將依據 GCC AI 政策工作小組的建議,拒絕任何由大型語言模型生成或衍生的「具法律重要性」程式碼貢獻。「具法律重要性」的門檻——約 15 行程式碼或文字——沿用既有的 GNU 專案維護者準則;低於此門檻的小型 AI 輔助修正仍可提交,但須在提交訊息中標註「Assisted-by:」標籤,測試案例則完全豁免此規範。這項政策並未限制將 AI 工具用於研究、除錯或程式碼審查——僅限制最終進入貢獻內容本身的產出——反映出的疑慮是:GPL 著佐權共享授權(copyleft)機制,仰賴貢獻者對自己的作品擁有明確著作權,而 LLM 生成的程式碼在這點上法律地位並不明確。",
    },
    tag: { en: "Content Licensing", zh: "內容授權" },
    topics: ["content-licensing", "machine-readable-policy"],
