    schemaVersion: "1.0",
    id: "topic-2026-000071",
    slug: "illinois-sb315-ai-safety-measures-act",
    title: {
      en: "Illinois Enacts Nation's Toughest State AI Safety Law",
      zh: "伊利諾州頒布全美最嚴格的州級 AI 安全法",
    },
    summary: {
      en: "Capitol News Illinois reports that Governor JB Pritzker signed SB 315, the Artificial Intelligence Safety Measures Act, into law on July 6, 2026, applying to \"large frontier developers\" with annual gross revenue exceeding $500 million whose models are trained using computing power above a set threshold. The law requires developers to publicly disclose safety practices and their framework for identifying \"catastrophic risk\" (incidents that could cause death or serious injury to 50 or more people, or over $1 million in property damage), report significant safety incidents within 72 hours (24 hours if death or serious injury is imminent), and undergo mandatory annual independent third-party safety audits -- making Illinois the first US state to require recurring third-party audits rather than one-time or self-attested review. The law also creates confidential reporting channels and whistleblower protections, carries civil penalties up to $1 million for a first violation and $3 million for subsequent ones, and takes effect January 1, 2028.",
      zh: "Capitol News Illinois 報導,伊利諾州州長 JB Pritzker 於 2026 年 7 月 6 日簽署《人工智慧安全措施法》(SB 315),適用對象為年營收超過 5 億美元、且模型訓練運算量超過特定門檻的「大型前沿開發商」。該法要求開發商公開揭露其安全實務,以及辨識「災難性風險」(可能導致 50 人以上死亡或重傷、或逾百萬美元財產損失的事故)的框架,並須在 72 小時內(若有立即死亡或重傷風險則為 24 小時內)通報重大安全事故,同時強制接受每年一次的獨立第三方安全稽核——使伊利諾州成為全美第一個要求「定期」而非一次性或自我聲明式第三方稽核的州。該法並建立保密通報管道與吹哨者保護機制,首次違反可處最高 100 萬美元、再犯最高 300 萬美元的民事罰鍰,自 2028 年 1 月 1 日起生效。",
    },
    tag: { en: "AI Governance", zh: "AI 治理" },
    topics: ["ai-governance", "frontier-safety"],
