    schemaVersion: "1.0",
    id: "topic-2026-000073",
    slug: "china-waico-shanghai-ai-governance",
    title: {
      en: "China Launches WAICO in Shanghai, Bypassing Western-Led AI Governance",
      zh: "中國在上海成立 WAICO,繞開西方主導的 AI 治理路線",
    },
    summary: {
      en: "Forbes reports that 29 nations -- including Russia, Belarus, Serbia, Cuba, Brazil, Venezuela, and Pakistan, but none of the United States, United Kingdom, European Union, Japan, or South Korea -- signed the charter establishing the World Artificial Intelligence Cooperation Organization (WAICO) in Shanghai on July 28, 2026. Headquartered in Shanghai, WAICO is framed as a China-led intergovernmental \"track\" for AI governance separate from Western institutions, with a stated focus on developing rules for model safety, data governance, and cross-border AI deployment, alongside capacity-building investment in AI research and training across the Global South (ASEAN, Africa, the Arab League, and Latin America).",
      zh: "《富比士》報導,29 個國家——包括俄羅斯、白俄羅斯、塞爾維亞、古巴、巴西、委內瑞拉與巴基斯坦,但不含美國、英國、歐盟、日本或南韓——於 2026 年 7 月 28 日在上海簽署憲章,成立「世界人工智慧合作組織」(WAICO)。WAICO 總部設於上海,被定位為由中國主導、獨立於西方機構之外的政府間 AI 治理「路線」,宣稱聚焦於制定模型安全、資料治理與跨境 AI 部署等規則,並對全球南方(東協、非洲、阿拉伯聯盟、拉丁美洲)的 AI 研究與人才培育進行能力建構投資。",
    },
