    schemaVersion: "1.0",
    id: "topic-2026-000074",
    slug: "constructive-alignment-preference-dynamics",
    title: {
      en: "Preprint Proposes \"Constructive Alignment\": Governing How AI Systems Shape Human Preferences Over Time",
      zh: "預印本提出「建構式對齊」:治理 AI 系統如何隨時間形塑人類偏好",
    },
    summary: {
      en: "A preprint by Max Kanwal and Caryn Tran (arXiv 2607.00001, submitted July 2, 2026) proposes \"Constructive Alignment,\" a control-theoretic reframing of AI alignment that treats human preferences not as a static target for an AI system to optimize against, but as something interactive AI systems actively and continuously shape through repeated interaction. The authors argue that because preferences are already dynamically constructed by engagement with AI systems, alignment work should explicitly govern that preference-formation process itself -- designing for coherence between an AI system's stated objectives and its actual downstream effect on how users' values evolve -- rather than treating preference elicitation as a one-time measurement problem.",
      zh: "Max Kanwal 與 Caryn Tran 發表的一篇預印本(arXiv 2607.00001,2026 年 7 月 2 日送件)提出「建構式對齊」(Constructive Alignment),以控制理論的角度重新框定 AI 對齊問題:主張人類偏好並非 AI 系統要優化逼近的靜態目標,而是互動式 AI 系統透過反覆互動主動、持續形塑出來的產物。作者認為,既然偏好本身就是在與 AI 系統互動的過程中被動態建構出來的,對齊工作就應該明確地治理這個偏好形成過程本身——設計時著重 AI 系統宣稱的目標,與其對使用者價值觀演變所造成的實際下游影響之間是否一致——而不是把偏好探詢當成一次性的量測問題來處理。",
    },
