    schemaVersion: "1.0",
    id: "topic-2026-000078",
    slug: "asago-ai-policy-as-code-red-hat-nvidia-ibm",
    title: {
      en: "Red Hat, NVIDIA, and IBM Back asago, an Open-Source Project That Turns AI Policy Into Deployable Code",
      zh: "Red Hat、NVIDIA、IBM 支持 asago:將 AI 政策轉為可部署程式碼的開源專案",
    },
    summary: {
      en: "AI News (artificialintelligence-news.com) reports that Red Hat launched asago, an open-source initiative backed by NVIDIA and IBM (with additional contributors including Brave Software, Microsoft, MIT Lincoln Laboratory, North Carolina State University, The Alan Turing Institute, the EvalEval coalition, and Austria's IT:U), aimed at automating the translation of organizational AI governance policy into deployable, auditable infrastructure code. The system maps an organization's stated policies against frameworks such as the NIST AI Risk Management Framework and the EU AI Act, generates targeted risk scenarios, recommends technical guardrails, and deploys the resulting controls as Kubernetes-orchestrated infrastructure code, maintaining an audit trail that links every active control back to the policy clause it implements. Red Hat frames the goal as closing the gap between slow manual compliance review and deploying AI systems with no governance controls at all, claiming the approach can cut deployment timelines from months to days.",
      zh: "《AI News》(artificialintelligence-news.com)報導,Red Hat 發起開源專案 asago,由 NVIDIA 與 IBM 支持(另有 Brave Software、Microsoft、MIT 林肯實驗室、北卡羅來納州立大學、艾倫圖靈研究所、EvalEval 聯盟與奧地利 IT:U 等貢獻者),目標是將組織的 AI 治理政策自動轉譯為可部署、可稽核的基礎設施程式碼。系統會將組織既定的政策對應到 NIST AI 風險管理框架、歐盟《AI 法案》等既有框架,產生對應的風險情境、建議技術防護措施,並將結果部署為由 Kubernetes 編排的基礎設施程式碼,同時維持一條把每項生效控制措施回溯連結到其所依據政策條文的稽核軌跡。Red Hat 將此定位為填補「緩慢的人工合規審查」與「完全無治理控制部署 AI 系統」兩個極端之間的落差,並宣稱這套做法可將部署時程從數月縮短為數日。",
    },
    tag: { en: "Machine-Readable Policy", zh: "機器可讀政策" },
