    slug: "delaware-artificial-intelligence-company-legal-entity",
    title: {
      en: "Delaware Proposes a New Legal Entity Letting AI Agents Run a Company's Day-to-Day Operations",
      zh: "德拉瓦州提案新法人型態,允許 AI 智能體管理公司日常營運",
    },
    summary: {
      en: "The D&O Diary reports that Delaware lawmakers, working with the Secretary of State's office and legal-AI company Norm Ai, drafted legislation creating a new corporate form called the \"Artificial Intelligence Company\" (AIC) -- an entity in which an AI agent, rather than a human officer, manages day-to-day business affairs, including entering contracts, owning property, and being a party to litigation. AICs would operate only inside a regulatory sandbox overseen by a committee including the Delaware Secretary of State, the state attorney general, the chief justice of the Delaware Supreme Court, and the chair of Delaware's AI Commission, expiring after 30 months unless extended or codified. The AIC's liability shield is tied to three statutory conditions: adequate capitalization, a maintained activity log, and disclosure of the entity's autonomous status to counterparties.",
      zh: "《The D&O Diary》報導,德拉瓦州議員與州務卿辦公室、法律 AI 公司 Norm Ai 合作,起草法案創設一種新法人型態「人工智慧公司」(Artificial Intelligence Company, AIC)——由 AI 智能體而非人類主管管理日常業務,包括簽訂合約、持有財產、以及成為訴訟當事人。AIC 僅能在監理沙盒內運作,監督委員會成員包括德拉瓦州州務卿、州檢察總長、德拉瓦州最高法院首席大法官與該州 AI 委員會主席,沙盒為期 30 個月,除非延長或正式立法否則到期失效。AIC 的責任保護以三項法定條件為前提:充足資本額、持續維護的活動紀錄,以及向交易對象揭露該實體的自主狀態。",
    },
