    slug: "fsb-ai-adoption-consultation-public-responses",
    title: {
      en: "Financial Stability Board Publishes 150+ Public Responses to Its AI-Adoption Consultation",
      zh: "金融穩定委員會公布 150 多份對其 AI 導入諮詢的公開回應",
    },
    summary: {
      en: "The Financial Stability Board (FSB) published, on August 6, 2026, the full set of public responses to its consultation on \"Sound Practices for Responsible Adoption of Artificial Intelligence,\" a draft report proposing governance, risk-management, and operational standards for financial institutions adopting AI, originally released June 10, 2026 with comments invited through July 22, 2026. Responses came from more than 150 organizations and individuals, spanning major banks, insurance associations, fintech companies, and independent experts. The FSB says it will publish a final report incorporating this feedback in the coming months, making this consultation a live input into how AI governance standards for the global financial sector get set.",
      zh: "金融穩定委員會(FSB)於 2026 年 8 月 6 日公布了其「負責任導入人工智慧健全實務」(Sound Practices for Responsible Adoption of Artificial Intelligence)諮詢文件收到的全部公開回應。該份原於 2026 年 6 月 10 日發布的草案報告,提出金融機構導入 AI 時應遵循的治理、風險管理與營運標準,徵詢意見期限至 7 月 22 日。此次收到超過 150 個機構與個人的回應,涵蓋主要銀行、保險公會、金融科技公司與獨立專家。FSB 表示將在未來數月內根據這些意見發布最終報告,使這次諮詢成為形塑全球金融部門 AI 治理標準的即時輸入管道。",
    },
