    schemaVersion: "1.0",
    id: "topic-2026-000081",
    slug: "privdpo-differential-privacy-preference-alignment",
    title: {
      en: "Preprint Introduces PrivDPO, a Differential-Privacy Method for Protecting Preference Data in LLM Alignment",
      zh: "預印本提出 PrivDPO:一種保護 LLM 對齊過程中偏好資料的差分隱私方法",
    },
    summary: {
      en: "A preprint by Yangfan Jiang, Fei Wei, Ergute Bao, Xiaokui Xiao, Yaliang Li, and Bolin Ding (arXiv 2608.05040, submitted August 5, 2026) introduces PrivDPO, a differential-privacy framework for Direct Preference Optimization (DPO), the technique used to align language models to human preferences. Rather than protecting an entire training example, PrivDPO protects only the relative preference signal between two candidate responses -- which human annotators, not model outputs, actually produce -- by injecting calibrated statistical noise along the one-dimensional axis that preference information flows through during optimization. The authors report this targeted approach achieves a substantially better privacy-utility trade-off than applying generic differential-privacy noise across the full training process, without requiring expensive per-example gradient computations.",
      zh: "Yangfan Jiang、Fei Wei、Ergute Bao、Xiaokui Xiao、Yaliang Li 與 Bolin Ding 發表的預印本(arXiv 2608.05040,2026 年 8 月 5 日送件)提出 PrivDPO,一種針對「直接偏好優化」(Direct Preference Optimization, DPO,用來將語言模型對齊人類偏好的技術)設計的差分隱私框架。PrivDPO 並非保護整筆訓練樣本,而是只保護兩個候選回應之間的相對偏好訊號本身(這是人類標註者、而非模型輸出所產生的資訊)——做法是沿著偏好資訊在優化過程中流動的單一維度軸,注入經校準的統計雜訊。作者指出,這種針對性做法在隱私與效用之間取得的權衡,明顯優於對整個訓練過程套用一般性差分隱私雜訊的做法,且不需要昂貴的逐樣本梯度運算。",
    },
    tag: { en: "Machine-Readable Policy", zh: "機器可讀政策" },
    topics: ["training-data-rights", "empirical-research"],
    contentType: "preprint",
    sourceType: "academic-journal",
