    schemaVersion: "1.0",
    id: "topic-2026-000082",
    slug: "colorado-chatbot-safety-act-hb26-1263",
    title: {
      en: "Colorado's Chatbot Safety Act (HB 26-1263) Nears Its August Effective Date as the First State Law Targeting Companion AI",
      zh: "科羅拉多州《聊天機器人安全法》(HB 26-1263) 即將生效,成為美國首部針對陪伴型 AI 的州級法律",
    },
    summary: {
      en: "Colorado's HB 26-1263, the Chatbot Safety Act, was signed by Governor Polis on May 29, 2026 and reaches general effectiveness on August 12, 2026 (operator obligations follow on January 1, 2027, with annual reporting duties beginning July 1, 2027). The law requires operators of conversational AI services to clearly disclose to users that they are interacting with AI rather than a human, and to use commercially reasonable methods to estimate a user's age. For minors specifically, operators must disable engagement-maximizing incentives, prevent the system from generating sexually explicit content, and avoid simulating emotional dependency. All operators must implement evidence-based response protocols for prompts involving suicidal ideation or self-harm, and report annually to the Colorado Attorney General on how those protocols performed in practice. Multiple legal and advocacy sources describe it as the first state-level law in the U.S. specifically targeting conversational and companion AI chatbots.",
      zh: "科羅拉多州 HB 26-1263《聊天機器人安全法》已於 2026 年 5 月 29 日由州長 Polis 簽署,將於 2026 年 8 月 12 日全面生效(業者義務條款自 2027 年 1 月 1 日起適用,年度通報義務則自 2027 年 7 月 1 日起適用)。該法要求對話式 AI 服務業者明確揭露使用者正在與 AI 互動、而非真人,並以商業上合理的方式估計使用者年齡。針對未成年使用者,業者須停用以提升黏著度為目的的獎勵機制、防止系統生成露骨性內容,並避免模擬情感依附關係。所有業者都必須針對涉及自殺意念或自我傷害的提示建立實證基礎的回應機制,並每年向科羅拉多州檢察總長回報這些機制的實際運作情況。多個法律與倡議機構的分析都指出,這是美國第一部專門針對對話式/陪伴型 AI 聊天機器人的州級法律。",
    },
    tag: { en: "AI Governance", zh: "AI 治理" },
    topics: ["ai-governance", "human-ai-relations"],
