    id: "topic-2026-000085",
    slug: "people-first-chatbot-act-hr9619",
    title: {
      en: "Federal \"People-First Chatbot Act\" (H.R. 9619) Would Bar AI Companies From Training on Minors' Data",
      zh: "美國聯邦《以人為本聊天機器人法》(H.R. 9619) 擬禁止 AI 公司使用未成年人資料訓練模型",
    },
    summary: {
      en: "Representatives Valerie Foushee (NC-04) and Greg Casar (TX-35) introduced H.R. 9619, the People-First Chatbot Act, on July 9, 2026, backed by privacy groups including EPIC, Fairplay, and the Consumer Federation of America. The bill would bar AI companies from using minors' input data to train chatbots, prohibit using any user's input data for training without knowledge or consent (requiring affirmative consent from adults), and require companies to make chatbots \"safe-by-design\" to mitigate harms such as compulsive use, emotional dependence, and suicide risk -- including disabling harmful design features specifically for minors. Enforcement would run through the FTC, state attorneys general, and a private right of action.",
      zh: "聯邦眾議員 Valerie Foushee(北卡州第 4 選區)與 Greg Casar(德州第 35 選區)於 2026 年 7 月 9 日提出 H.R. 9619《以人為本聊天機器人法》,獲 EPIC、Fairplay、美國消費者聯盟等隱私團體支持。法案擬禁止 AI 公司使用未成年使用者的輸入資料訓練聊天機器人,禁止在未經使用者知情或同意下使用其輸入資料訓練模型(成年人須明確同意),並要求業者採「設計即安全」原則以降低強迫性使用、情感依附、自殺風險等傷害——包含針對未成年使用者停用具傷害性的設計功能。執法機制涵蓋聯邦貿易委員會、各州檢察總長,以及私人訴訟權。",
    },
    tag: { en: "AI Governance", zh: "AI 治理" },
    topics: ["ai-governance", "human-ai-relations"],
