    schemaVersion: "1.0",
    id: "topic-2026-000086",
    slug: "un-global-dialogue-ai-governance-guterres-priorities",
    title: {
      en: "At the UN's First Global Dialogue on AI Governance, Guterres Calls for an AI Child Safety Pledge",
      zh: "聯合國首屆「AI 治理全球對話」上,古特雷斯呼籲各國採納「AI 兒童安全承諾」",
    },
    summary: {
      en: "The UN's first Global Dialogue on AI Governance, mandated by a General Assembly resolution and jointly organized by the ITU, UNESCO, and the UN Office for Digital and Emerging Technologies, convened July 6-7, 2026 in Geneva -- described as the first time all UN member states sat together specifically to discuss AI governance. Secretary-General Antonio Guterres called for nations to adopt an \"AI Child Safety Pledge,\" under which developers would need to prove systems are tested for safety before children can access them, commit to \"zero tolerance\" for sexual abuse content, and ensure systems that detect a child in distress stop and connect them to real human support. He also stressed that AI \"must never strip away dignity or entrench discrimination\" and that humans must retain the final decision in high-stakes domains like justice, healthcare, and policing; highlighted the UN AI Environmental Transparency Initiative, requiring companies to publicly disclose carbon, water, and land footprints with a commitment to renewable-powered data centers by 2030; and announced backing from over 20 countries for a new UN-supported Global Network for Exchange and Cooperation on AI Capacity Building aimed at developing nations.",
      zh: "聯合國首屆「AI 治理全球對話」由大會決議授權設立,由國際電信聯盟(ITU)、聯合國教科文組織(UNESCO)與聯合國數位與新興技術辦公室共同主辦,於 2026 年 7 月 6 至 7 日在日內瓦召開——被形容為聯合國全體會員國首次專門就 AI 治理齊聚一堂。秘書長古特雷斯呼籲各國採納「AI 兒童安全承諾」,要求開發者在兒童可使用系統前先證明已完成安全測試、對性虐待內容採取「零容忍」,並確保系統偵測到兒童陷入困境時能暫停並轉介真人協助。他同時強調 AI「絕不能剝奪人性尊嚴或加深歧視」,司法、醫療、警務等高風險決策的最終判斷仍須由人類做出;並宣布「聯合國 AI 環境透明倡議」,要求企業公開揭露碳、水、土地足跡,並承諾 2030 年前以再生能源供電資料中心;另有 20 多國支持成立新的「聯合國支持之 AI 能力建構交流合作全球網絡」,協助開發中國家取得 AI 技術。",
    },
    tag: { en: "AI Governance", zh: "AI 治理" },
