    id: "topic-2026-000087",
    slug: "vietnam-decision-33-2026-high-risk-ai-systems",
    title: {
      en: "Vietnam Issues Official List of 46 High-Risk AI Systems Across Six Sectors",
      zh: "越南公布六大領域共 46 項高風險 AI 系統正式清單",
    },
    summary: {
      en: "Vietnam's Deputy Prime Minister Ho Quoc Dung signed Decision 33/2026/QD-TTg on June 30, 2026, identifying AI systems posing significant risk to life, health, individual and organizational rights, or national security. The decision designates 46 high-risk systems across six sectors: transportation (31 systems, including automated vehicle control and traffic-signal systems), ethnicity and religion (7, including scoring applications for policy benefits), education (3, including self-learning content providers and learner-evaluation tools), healthcare (2, including AI-integrated surgical robots), banking (2, including large-value transaction execution and credit-decision systems), and litigation (1, large-scale biometric identification for civil cases). It takes effect August 15, 2026, requiring providers to report systems to the Ministry of Science and Technology before use, maintain an ongoing risk-management plan, and complete conformity assessments before and during deployment, with compliance deadlines of March 1, 2027 for most sectors and September 1, 2027 for education, healthcare, and banking.",
      zh: "越南副總理胡國勇於 2026 年 6 月 30 日簽署第 33/2026/QD-TTg 號決定,認定對生命、健康、個人與組織權益或國家安全構成重大風險的 AI 系統。該決定將 46 項高風險系統劃分為六大領域:運輸(31 項,含自動車輛控制與交通號誌系統)、民族與宗教(7 項,含政策福利評分應用)、教育(3 項,含自主學習內容提供者與學習者評量工具)、醫療(2 項,含 AI 整合手術機器人)、銀行(2 項,含大額交易執行與信用決策系統),以及訴訟(1 項,大規模生物特徵識別用於民事案件)。該決定將於 2026 年 8 月 15 日生效,要求業者在使用前向科學技術部報備系統、持續維持風險管理計畫,並在部署前後完成符合性評估,多數領域合規期限為 2027 年 3 月 1 日,教育、醫療、銀行領域則為 2027 年 9 月 1 日。",
    },
