    schemaVersion: "1.0",
    id: "topic-2026-000088",
    slug: "ninth-circuit-cfaa-ai-agent-access-amazon-perplexity",
    title: {
      en: "Ninth Circuit Rules AI Shopping Agents Don't \"Access\" Sites Under Anti-Hacking Law -- the User Does",
      zh: "第九巡迴法院裁定:AI 購物助理不算「存取」網站觸犯反駭客法——是使用者在存取",
    },
    summary: {
      en: "The U.S. Court of Appeals for the Ninth Circuit ruled on August 4, 2026 in Amazon v. Perplexity that when a user directs an AI shopping agent to browse a third-party site on their behalf, it is the user -- not the AI company -- who \"accesses\" that site under the Computer Fraud and Abuse Act (CFAA). The court found that because Perplexity's agent communicated with Amazon's servers by routing through the user's own computer rather than contacting Amazon directly, Perplexity itself did not \"access\" Amazon's systems within the statute's meaning. Practically, this means platforms cannot rely on the CFAA -- the main U.S. federal anti-hacking statute -- as a tool to block or penalize user-directed AI agents; they're left with terms-of-service enforcement and contract or tort claims instead. The court left open that agents with \"greater autonomy\" or direct server-to-server communication might be treated differently.",
      zh: "美國聯邦第九巡迴上訴法院於 2026 年 8 月 4 日在 Amazon v. Perplexity 一案中裁定:當使用者指示 AI 購物助理代為瀏覽第三方網站時,依《電腦詐欺與濫用法》(CFAA),「存取」該網站的是使用者本人,不是 AI 公司。法院認定,由於 Perplexity 的助理是透過使用者自己的電腦與 Amazon 伺服器通訊、而非直接聯繫 Amazon,因此 Perplexity 本身在該法條意義下並未「存取」Amazon 系統。實務上,這代表平台無法再靠 CFAA——美國聯邦主要的反駭客法規——來封鎖或制裁由使用者指揮的 AI 助理,只能改採服務條款執法或契約、侵權訴訟等途徑。法院同時保留了但書:自主性「更高」或直接與伺服器通訊的助理,可能會被以不同方式認定。",
    },
    tag: { en: "Agent Autonomy", zh: "智能體自主性" },
    topics: ["ai-governance", "agent-autonomy"],
