    schemaVersion: "1.0",
    id: "topic-2026-000089",
    slug: "california-ai-transparency-act-operative",
    title: {
      en: "California's AI Transparency Act Takes Operative Effect, Mandating Watermarking and Free Detection Tools",
      zh: "加州《AI 透明法案》正式生效,強制要求浮水印標記與免費偵測工具",
    },
    summary: {
      en: "California's AI Transparency Act (SB 942, signed 2024, expanded and delayed by AB 853 in 2025) became operative on August 2, 2026, making California the first U.S. state to enforce mandatory AI content provenance and detection requirements. Generative AI providers with more than 1 million monthly California users or visitors must: offer a free, publicly accessible tool (web and API) letting anyone check whether content was AI-generated, without retaining submitted content or collecting unnecessary personal data; embed permanent, machine-readable \"latent provenance\" metadata -- provider name, system name/version, creation timestamp, unique content ID, typically via C2PA standards -- into AI-generated or substantially altered images, video, and audio; and let users optionally add a visible \"AI-generated\" label. Non-compliance carries penalties of $5,000 per violation, with each day counting separately. The delayed effective date was set to align with the EU AI Act's Article 50 transparency-obligation timeline.",
      zh: "加州《AI 透明法案》(SB 942,2024 年簽署,2025 年由 AB 853 擴大範圍並延後生效日)已於 2026 年 8 月 2 日正式生效,使加州成為美國第一個強制執行 AI 內容來源與偵測要求的州。每月加州使用者或造訪者超過 100 萬人的生成式 AI 業者必須:提供一個免費、公開可用的工具(網頁與 API),讓任何人都能查核內容是否由 AI 生成,且不得保留提交內容或蒐集非必要的個人資料;在 AI 生成或大幅修改的圖片、影片、音訊中嵌入永久、機器可讀的「潛在來源」metadata——業者名稱、系統名稱/版本、建立時間戳記、唯一內容 ID,通常採用 C2PA 標準;並讓使用者可選擇加上可見的「AI 生成」標籤。違規每次處以 5,000 美元罰款,且每一天未合規都各自獨立計算。延後的生效日是為了配合歐盟《AI 法案》第 50 條透明義務的時程。",
    },
    tag: { en: "Machine-Readable Policy", zh: "機器可讀政策" },
