    id: "topic-2026-000105",
    slug: "australia-national-ai-plan-digital-duty-of-care",
    title: {
      en: "Australia's National AI Plan Leans on a Proposed \"Digital Duty of Care\" Rather Than New AI-Specific Law",
      zh: "澳洲《國家 AI 計畫》靠「數位注意義務」而非新訂 AI 專法",
    },
    summary: {
      en: "Australia's federal government has set out five national AI safety priorities under its National AI Plan, according to an analysis by the ADM+S Centre (the Australian Research Council's Centre of Excellence for Automated Decision-Making and Society) published July 22, 2026: a proposed statutory \"digital duty of care\" requiring AI and digital-service providers to take reasonable steps to prevent foreseeable harms; a second round of privacy-law reform consultation; AI safety in the workplace; consumer protections against surveillance pricing and AI agent-based commerce; and a framework to regulate government agencies' own use of automated decision-making. The plan is explicitly built around \"the adaptability of existing laws to deal with AI risks\" rather than a comprehensive new AI-specific statute, paired with a newly funded AI Safety Institute (AU$29.9 million over four years). The digital duty of care itself is not new policy -- the government first committed to it in late 2024, with consultations running since 2025 -- but the analysis frames it as the most substantive of the five priorities, since it would place an affirmative, forward-looking obligation on AI providers rather than relying only on after-the-fact enforcement of existing law.",
      zh: "根據澳洲研究委員會「自動化決策與社會」卓越中心(ADM+S Centre)於 2026 年 7 月 22 日發布的分析,澳洲聯邦政府在其《國家 AI 計畫》下訂出五項國家 AI 安全優先事項:一項擬議中的法定「數位注意義務」,要求 AI 與數位服務提供者採取合理措施防止可預見的傷害;第二輪隱私法改革諮詢;職場 AI 安全;針對監控定價與 AI 代理式商務的消費者保護;以及一套規範政府機關自身使用自動化決策的框架。整份計畫明確建立在「運用現行法律的彈性因應 AI 風險」之上,而非制定一部全面的新 AI 專法,並搭配一個新獲撥款的 AI 安全研究院(四年內 2,990 萬澳幣)。「數位注意義務」本身並非新政策——政府早在 2024 年底就已承諾推動,2025 年起持續進行諮詢——但這份分析認為,五項優先事項中它是最具實質意義的一項,因為它會為 AI 提供者設下一項具前瞻性的積極義務,而不只是仰賴對現行法律的事後執法。",
    },
    tag: { en: "AI Governance", zh: "AI 治理" },
    topics: ["ai-governance"],
    contentType: "analysis",
    sourceType: "university",
    sourceName: "ADM+S Centre",
    sourceUrl: "https://www.admscentre.org.au/more-ai-safety-priorities/",
