    schemaVersion: "1.0",
    id: "topic-2026-000106",
    slug: "biocomputer-consciousness-moral-status-public-attitudes-study",
    title: {
      en: "Study Finds a \"Consciousness-Ethics Paradox\" in Public Attitudes Toward Brain-Organoid Biocomputers",
      zh: "研究發現公眾對腦類器官生物電腦的態度存在「意識—倫理悖論」",
    },
    summary: {
      en: "A study published in Neuroscience of Consciousness (Oxford University Press, July 8, 2026) by Jonathan Lomax Boyd, Eric Allen Jensen, Aaron Michael Jensen, and Nethanel Lipshitz, \"Views on the distribution of consciousness influence ethical judgements toward brain organoids as biological computers: an exploratory study,\" surveyed public attitudes toward biocomputers -- computing systems built from living brain organoid tissue. Respondents split into three clusters: about 20% attributed high consciousness broadly, including to AI and organoids; 32% showed a graded reduction in attributed consciousness beyond humans; and 47% limited consciousness essentially to conventional nervous systems. Overall, 94% of respondents rated adult humans as at least moderately conscious, versus only about 13% who rated human brain-organoid models that way. Despite this generally low consciousness attribution, support for biocomputer research was high across the sample: 79.3% either agreed or strongly agreed with supporting it. The most counterintuitive finding ran opposite to what standard moral-status reasoning would predict: within the two clusters most willing to attribute some consciousness to organoids, support for research increased, not decreased, as their perceived consciousness increased -- the authors frame this as a \"consciousness-ethics paradox\" that complicates the usual assumption that attributing more mind to an entity should make people more protective of it.",
      zh: "一篇發表於《意識神經科學》(Neuroscience of Consciousness,牛津大學出版社,2026 年 7 月 8 日)的研究——作者為 Jonathan Lomax Boyd、Eric Allen Jensen、Aaron Michael Jensen 與 Nethanel Lipshitz,題為〈對意識分布的看法如何影響對作為生物電腦的腦類器官的倫理判斷:一項探索性研究〉——調查了公眾對「生物電腦」(用活體腦類器官組織打造的運算系統)的態度。受訪者分成三群:約 20% 廣泛歸予高度意識,包含 AI 與類器官在內;32% 對人類以外的實體呈現漸層式遞減的意識歸屬;47% 則基本上只把意識限定在傳統神經系統上。整體而言,94% 的受訪者認為成年人「極度有意識」或「中度有意識」,相對之下只有約 13% 對人類腦類器官模型做出同等評分。儘管整體意識歸屬偏低,對生物電腦研究的支持度卻很高:79.3% 的受訪者「同意」或「非常同意」支持這類研究。最違反直覺的發現方向恰好相反於標準道德地位推理的預期:在最願意賦予類器官某種意識的兩個群體裡,隨著他們認為的意識程度升高,對研究的支持度不減反增——作者將此稱為「意識—倫理悖論」,挑戰了「賦予一個實體越多心智,人們就該對它越保護」這個常見假設。",
    },
    tag: { en: "Empirical Research", zh: "實證研究" },
    topics: ["empirical-research", "moral-status"],
    contentType: "academic-paper",
    sourceType: "academic-journal",
    sourceName: "Neuroscience of Consciousness (Oxford University Press)",
