    schemaVersion: "1.0",
    id: "topic-2026-000107",
    slug: "senate-hearing-ai-surveillance-pricing-hawley",
    title: {
      en: "Senate Judiciary Subcommittee Holds Bipartisan Hearing on AI-Driven \"Surveillance Pricing\"",
      zh: "參議院司法委員會就 AI「監控定價」召開跨黨派聽證會",
    },
    summary: {
      en: "The U.S. Senate Judiciary Committee's Subcommittee on Crime and Counterterrorism held a hearing titled \"Your Data, Their Profit: The Consumer Cost of AI Surveillance Pricing\" on August 4, 2026, examining how companies use AI, personal data, and behavioral profiles to set individualized prices for the same goods and services. Subcommittee chairman Senator Josh Hawley (R-Mo.) called the practice \"the unholy trinity of everything Americans hate: spying on people, ripping them off, and taking away jobs,\" and \"one of the biggest scams in American history.\" Robert Hedges, a former Visa chief data officer now at MIT, testified that \"no consumer would willingly supply personal data to third parties to be used against them,\" while Wharton professor Z. John Zhang cautioned that personalized pricing's benefits accrue mainly to companies with strong brands and loyal customers, not to consumers generally. The hearing drew bipartisan agreement: Senator Richard Blumenthal (D-Conn.) called for federal action, saying \"We need a federal law. We need federal standards. We need national safeguards.\" Witnesses noted that Connecticut has banned retail surveillance pricing outright, Maryland and New Jersey have banned it specifically for groceries, and New York is transitioning from a disclosure requirement toward an outright ban -- while no comparable federal standard yet exists.",
      zh: "美國參議院司法委員會犯罪暨反恐小組委員會於 2026 年 8 月 4 日召開題為〈你的資料,他們的利潤:AI 監控定價對消費者的代價〉的聽證會,檢視企業如何運用 AI、個人資料與行為輪廓,對相同商品或服務向不同消費者訂出個別化價格。小組委員會主席、參議員 Josh Hawley(共和黨,密蘇里州)稱這種做法是「美國人痛恨的一切事物的邪惡三位一體:監控人民、剝削人民、奪走工作機會」,並稱之為「美國史上最大的騙局之一」。曾任 Visa 資料長、現任麻省理工學院數位研究員的 Robert Hedges 作證表示:「沒有任何消費者會自願把個人資料提供給第三方,讓對方拿來對付自己。」賓州大學華頓商學院教授 Z. John Zhang 則提醒,個人化定價的好處主要落在品牌力強、忠誠顧客多的企業身上,而非普遍嘉惠消費者。聽證會出現跨黨派共識:參議員 Richard Blumenthal(民主黨,康乃狄克州)呼籲聯邦行動,表示「我們需要一部聯邦法律。我們需要聯邦標準。我們需要全國性保障。」證人指出,康乃狄克州已全面禁止零售監控定價,馬里蘭州與紐澤西州則針對雜貨業禁止此做法,紐約州正從揭露義務轉向全面禁止——而目前尚無對應的聯邦標準。",
    },
    tag: { en: "AI Governance", zh: "AI 治理" },
