    schemaVersion: "1.0",
    id: "topic-2026-000111",
    slug: "copyright-genai-lifecycle-ucl-workshop-kluwer",
    title: {
      en: "UCL/KU Leuven Workshop Report Maps Where Copyright Law Breaks Down Across the Generative-AI Lifecycle",
      zh: "UCL 與魯汶大學工作坊報告:剖析著作權法在生成式 AI 生命週期各階段的失靈之處",
    },
    summary: {
      en: "Alina Trapova and James Hall (University College London Centre for AI and Institute of Brand and Innovation Law) and Thomas Margoni and Leona King (KU Leuven Centre for IT & IP Law) published \"Copyright across the genAI lifecycle -- views from computer science and law\" on the Kluwer Copyright Blog (Wolters Kluwer) on August 13, 2026, reporting on an interdisciplinary workshop held at UCL on March 13, 2026, that brought together legal scholars and computer scientists. The report walks through how copyright doctrine is applied at each stage of building and running generative AI systems -- data collection, model training, and post-training systems such as retrieval-augmented generation (RAG) -- and identifies where existing frameworks strain against the underlying technology. Key tensions discussed include persistent uncertainty over what counts as \"lawful access\" to training data under EU and UK law, how territorial copyright doctrines cope poorly with AI systems that are trained and deployed across borders, the gap between technical and legal understandings of what it means for a model to \"memorize\" content, how liability could be allocated across a multi-party AI supply chain, and how core copyright concepts like reproduction were built around discrete human-authored works and now face pressure when applied to AI-generated or AI-mediated outputs.",
      zh: "倫敦大學學院(UCL)AI 中心暨品牌與創新法律研究所的 Alina Trapova 與 James Hall,以及魯汶大學(KU Leuven)資訊科技與智慧財產權法中心的 Thomas Margoni 與 Leona King,於 2026 年 8 月 13 日在 Kluwer Copyright Blog(Wolters Kluwer)發表〈生成式 AI 生命週期中的著作權——來自電腦科學與法律的觀點〉(Copyright across the genAI lifecycle),報導了 2026 年 3 月 13 日在 UCL 舉辦、匯集法律學者與電腦科學家的跨領域工作坊內容。報告逐一檢視著作權原則在建構與運行生成式 AI 系統各階段——資料蒐集、模型訓練、以及檢索增強生成(RAG)等訓練後系統——的適用情形,並指出現有法律框架在哪些地方與底層技術產生摩擦。討論的主要張力包括:歐盟與英國法下何謂訓練資料的「合法取用」仍高度不確定;屬地主義的著作權原則難以應對跨國訓練與部署的 AI 系統;「記憶化」(memorization)在技術理解與法律理解上的落差;AI 多方供應鏈之間責任該如何分配;以及「重製」等核心著作權概念原本是針對個別人類創作的作品而設計,如今套用在 AI 生成或 AI 中介的產出上正面臨壓力。",
    },
    tag: { en: "Content Licensing", zh: "內容授權" },
    topics: ["content-licensing", "training-data-rights"],
