    slug: "bytedance-mpa-copyright-accord-seedance-seedream",
    title: {
      en: "ByteDance and the Motion Picture Association Reach Copyright Accord Over AI Video and Image Tools",
      zh: "字節跳動與美國電影協會就 AI 影像生成工具達成著作權協議",
    },
    summary: {
      en: "Reuters reported on August 17, 2026 that ByteDance and the Motion Picture Association (MPA), Hollywood's leading film-industry trade group, reached an agreement to strengthen intellectual-property safeguards for ByteDance's Seedance (video generation) and Seedream (image generation) AI models. The accord follows a cease-and-desist letter the MPA sent in February 2026, after studios including Disney raised concerns that the technology could generate content featuring copyrighted characters and celebrity likenesses without authorization. Under the agreement, both parties commit to continuing collaboration on copyright protections as the underlying AI technology evolves; updated versions of ByteDance's models reportedly now include enhanced safeguards, with the technology distributed through TikTok, CapCut, and Dreamina.",
      zh: "路透社(Reuters)於 2026 年 8 月 17 日報導,字節跳動(ByteDance)與代表好萊塢電影業的主要貿易團體美國電影協會(Motion Picture Association, MPA)達成協議,強化其 Seedance(影片生成)與 Seedream(圖像生成)AI 模型的智慧財產權防護措施。此協議是在 MPA 於 2026 年 2 月發出停止侵權函之後促成的,當時包括迪士尼在內的片商擔心該技術可能未經授權生成含有受著作權保護角色與名人肖像的內容。根據協議,雙方承諾在底層 AI 技術持續演進的過程中維持著作權保護方面的合作;字節跳動的模型更新版本據報已納入強化的防護機制,相關技術透過 TikTok、CapCut 與 Dreamina 提供。",
    },
