    id: "topic-2026-000120",
    slug: "komca-ai-assisted-music-copyright-registration-reversal",
    title: {
      en: "South Korea's KOMCA Reverses Ban on Registering AI-Assisted Musical Works",
      zh: "南韓音樂著作權協會(KOMCA)撤銷 AI 輔助音樂作品的登記禁令",
    },
    summary: {
      en: "Sheppard Mullin attorneys Keith Kelly and Yeeun Kim reported on August 18, 2026 that the Korea Music Copyright Association (KOMCA), South Korea's largest music copyright collective, reversed its prior \"zero percent\" policy (in effect since March 24, 2025) that had required creators to confirm a work was made solely through human creative contribution with no AI involvement. Under the revised standards, announced in a notice dated August 4, 2026 and effective immediately, KOMCA will register AI-assisted works where a human creator made a substantial and leading creative contribution -- per KOMCA's updated registration form, meaning human creative involvement must account for more than half of the creative process -- while drawing a bright line against prompt-only generation. Registration now requires detailed disclosure of exactly which parts of a work involved AI, which tools were used and how, and the human contribution to each element (lyrics, composition, arrangement), plus documentary proof such as digital-audio-workstation project files, revision histories, and prompt logs that KOMCA may request and review through a technical-check or internal-deliberation process. The article notes false filings carry meaningful financial and contractual risk.",
      zh: "Sheppard Mullin 律師事務所的 Keith Kelly 與 Yeeun Kim 於 2026 年 8 月 18 日報導,南韓最大的音樂著作權協會「韓國音樂著作權協會」(KOMCA)撤銷了先前的「零 AI」政策(自 2025 年 3 月 24 日起實施)——該政策原本要求創作者確認作品完全由人類創作、不含任何 AI 參與。根據 2026 年 8 月 4 日發布、即刻生效的新標準,KOMCA 將登記由人類創作者做出實質且主導性創作貢獻的 AI 輔助作品——依 KOMCA 更新後的登記表格,人類創作參與須佔創作過程一半以上——但明確劃定界線:純粹由提示詞(prompt)生成的作品不予登記。登記現在要求詳細揭露作品中哪些部分涉及 AI、使用了哪些工具及如何使用,以及人類對每個元素(歌詞、作曲、編曲)的貢獻;並須提供佐證文件,例如數位音訊工作站(DAW)專案檔、修改紀錄與提示詞紀錄,KOMCA 可要求提交並透過技術查核或內部審議程序覆核。報導指出,不實申報將帶來實質的財務與合約風險。",
    },
    tag: { en: "Content Licensing", zh: "內容授權" },
