    id: "topic-2026-000123",
    slug: "round-hill-music-copyright-lawsuits-suno-anthropic",
    title: {
      en: "Round Hill Music Sues Suno and Anthropic for Copyright Infringement, Seeking Up to $1 Billion",
      zh: "Round Hill Music 對 Suno 與 Anthropic 提起著作權訴訟,求償上看 10 億美元",
    },
    summary: {
      en: "Music publisher Round Hill Music filed copyright infringement lawsuits against AI music-generation company Suno and against Anthropic on August 17, 2026, according to Music Business Worldwide. Against Suno, Round Hill alleges direct copyright infringement, circumvention of DMCA access controls, and removal of copyright management information, and separately names Bright Data Ltd. for allegedly supplying the proxy networks and scraping tools used to obtain music and lyrics from licensed platforms. Against Anthropic, Round Hill alleges similar direct-infringement and DMCA claims, and -- notably -- cites Claude's own assessment of its song-rewriting outputs, which reportedly judged the results as landing \"very close to the originals: same structure, same hooks reused with light rewording,\" constituting \"reproducing the copyrighted song.\" Each suit names 500 compositions as \"representative bellwethers\" -- including \"Iris\" (Goo Goo Dolls), \"Total Eclipse of the Heart\" (Bonnie Tyler), and \"I Got You (I Feel Good)\" (James Brown) -- with Round Hill saying it plans to amend both cases to cover potentially ten thousand or more works. It is seeking up to $150,000 per work in statutory damages, with total exposure that could conceivably exceed $1 billion, and has stated it has no intention of settling either case. Anthropic is already defending three other music-copyright suits in the same court from Concord/Universal Music Publishing/ABKCO and BMG Rights Management.",
      zh: "根據 Music Business Worldwide 報導,音樂出版商 Round Hill Music 於 2026 年 8 月 17 日對 AI 音樂生成公司 Suno 與 Anthropic 分別提起著作權侵權訴訟。針對 Suno,Round Hill 主張直接著作權侵權、規避 DMCA 存取控制措施,以及移除著作權管理資訊,另外還點名 Bright Data Ltd.,指控其提供代理伺服器網路與擷取工具,協助 Suno 從授權平台取得音樂與歌詞。針對 Anthropic,Round Hill 提出類似的直接侵權與 DMCA 主張,並且——值得注意的是——引用了 Claude 自己對其歌曲改寫輸出的評估,據報導 Claude 判斷這些結果「與原曲非常接近:結構相同、鉤子〔hook〕重複使用只是措辭略作修改」,構成「重製受著作權保護的歌曲」。兩起訴訟各自列出 500 首作為「代表性指標作品」——包括 Goo Goo Dolls 的〈Iris〉、Bonnie Tyler 的〈Total Eclipse of the Heart〉與 James Brown 的〈I Got You (I Feel Good)〉——Round Hill 表示計畫修改訴狀,將涵蓋範圍擴大到可能上萬首作品。求償金額為每件作品最高 15 萬美元法定賠償金,總求償額有可能超過 10 億美元;Round Hill 表示兩起案件都無意和解。Anthropic 目前在同一法院已在應訴另外三起音樂著作權訴訟,分別來自 Concord/環球音樂出版集團/ABKCO,以及 BMG Rights Management。",
    },
