    id: "topic-2026-000124",
    slug: "ftc-petition-ai-companies-hoard-and-destroy-books",
    title: {
      en: "Advocacy Coalition Petitions FTC Over AI Companies' 'Hoard-and-Destroy' Book Scanning Practices",
      zh: "民間團體聯盟請願聯邦貿易委員會,調查 AI 公司「囤積後銷毀」書籍掃描做法",
    },
    summary: {
      en: "A coalition of more than a dozen public-interest and consumer-advocacy groups -- including the Demand Progress Education Fund, the Consumer Federation of America, and the Institute for Local Self-Reliance -- sent a letter to the U.S. Federal Trade Commission on August 21, 2026 urging it to investigate AI developers, naming Anthropic and Amazon specifically, over a practice the coalition calls \"hoard-and-destroy\": buying print books in bulk, digitizing them into proprietary training datasets, and then destroying the physical copies, including rare and out-of-print editions with no surviving alternative copy. The coalition argues this permanently removes nonrenewable cultural material from public access and constitutes an unfair method of competition under Section 5 of the FTC Act, since only well-capitalized incumbents can absorb the cost of acquiring and destroying books at this scale, closing off the same training-data pathway to smaller competitors.",
      zh: "由十餘個公共利益與消費者權益團體組成的聯盟——包括 Demand Progress Education Fund、Consumer Federation of America 與 Institute for Local Self-Reliance——於 2026 年 8 月 21 日致函美國聯邦貿易委員會(FTC),敦促其調查 AI 開發商,並點名 Anthropic 與 Amazon,指控這些公司採行聯盟所稱的「囤積後銷毀」做法:大量購入紙本書籍、將其數位化納入專屬訓練資料集,再銷毀實體書,其中包括絕版且無其他留存副本的稀有版本。聯盟主張,此舉永久剝奪公眾取用不可再生文化材料的機會,並構成《FTC 法》第 5 條所禁止的不公平競爭手段,因為唯有資本雄厚的既有業者才能負擔以此規模收購並銷毀書籍的成本,藉此堵住其他規模較小競爭者取得相同訓練資料的途徑。",
    },
