    slug: "inadvertent-context-leakage-language-models",
    title: {
      en: "Study Finds LLMs Leak In-Context Secrets Through Ordinary Outputs, Worse in More Capable Models",
      zh: "研究發現大型語言模型會透過一般輸出洩漏情境內機密,且能力越強的模型洩漏越嚴重",
    },
    summary: {
      en: "Jaiden Fairoze, Neal Mangaokar, Kamalika Chaudhuri, Sanjam Garg, and Saeed Mahloujifar published \"Inadvertent Context Leakage in Language Models\" on arXiv on August 20, 2026, showing that merely holding sensitive user context (calendars, credentials, health records, financial data) in a model's context window creates hidden statistical correlations in its ordinary, non-adversarial outputs -- correlations an adaptive black-box attack can exploit even when the model correctly refuses direct requests to reveal the secret. Across controlled experiments on eight proprietary models, the attack reconstructed 2-digit in-context secrets with near-perfect accuracy and 4-digit secrets with 82% exact-match accuracy. The authors found that stronger instruction-following capability amplifies the leakage rather than reducing it, suggesting the vulnerability scales with model capability rather than being a patchable bug, and demonstrated two practical exploits: a classifier that infers sensitive predicates (health conditions, financial events) from routine outputs, and a reinforcement-learning-trained adversary that extracted full Social Security numbers from a production-style AI agent.",
      zh: "Jaiden Fairoze、Neal Mangaokar、Kamalika Chaudhuri、Sanjam Garg 與 Saeed Mahloujifar 於 2026 年 8 月 20 日在 arXiv 發表〈語言模型中的非蓄意情境洩漏〉(Inadvertent Context Leakage in Language Models),指出僅僅將敏感使用者情境(行事曆、憑證、健康紀錄、財務資料)置於模型的情境視窗中,即會在模型一般、非對抗性的輸出裡產生隱藏的統計相關性——即使模型正確拒絕直接洩露機密的請求,攻擊者仍可透過一種自適應黑箱攻擊手法加以利用。在對八個專有模型進行的受控實驗中,該攻擊以近乎完美的準確率重建二位數的情境內機密,並以 82% 的完全相符率重建四位數機密。研究者發現,模型的指令遵循能力越強,洩漏情況反而越嚴重,顯示此弱點是能力提升的副產品,而非可輕易修補的錯誤;研究並展示了兩種實際可行的攻擊:一是從一般輸出推斷敏感語義(如健康狀況、財務事件)的分類器,二是透過強化學習訓練、能從生產環境風格的 AI 代理中擷取完整社會安全號碼的對抗模型。",
    },
